COL={'jos':'#3ee0a1','jdg':'#ff9f43','rut':'#f472b6','1sa':'#5cc8ff','2sa':'#4f8bff','1ki':'#b78cff','2ki':'#8e7bff','1ch':'#ffcb5c','2ch':'#f5a524','ezr':'#2dd4bf','neh':'#22c3ee','est':'#ff6fa5'}
def cycle():
    N=[('😈','犯罪','行耶和华眼中看为恶的事'),('⛓️','受压','神把他们交在敌人手中'),('🙏','哀求','就呼求耶和华'),('🗡️','拯救','耶和华为他们兴起士师'),('🕊️','太平','国中太平……年')]
    cx,cy,r=260,250,150; s='<svg viewBox="0 0 520 500" role="img" aria-label="士师记的循环">'
    s+=f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="none" stroke="var(--orange)" stroke-width="4" class="flow" opacity=".75"/>'
    for i,(e,n,d) in enumerate(N):
        a=-math.pi/2+i*2*math.pi/5; x=cx+r*math.cos(a); y=cy+r*math.sin(a)
        s+=f'<circle cx="{x:.0f}" cy="{y:.0f}" r="40" fill="var(--card2)" stroke="var(--orange)" stroke-width="2.5"/><text x="{x:.0f}" y="{y+2:.0f}" text-anchor="middle" font-size="24">{e}</text><text x="{x:.0f}" y="{y+24:.0f}" text-anchor="middle" class="cn">{n}</text>'
        tx=cx+(r+70)*math.cos(a); ty=cy+(r+62)*math.sin(a)
        s+=f'<text x="{max(70,min(450,tx)):.0f}" y="{max(18,min(490,ty)):.0f}" text-anchor="middle" class="cs">{d}</text>'
    s+=f'<text x="{cx}" y="{cy-8}" text-anchor="middle" class="cn" fill="var(--red)">!! 每一圈更坏 !!</text><text x="{cx}" y="{cy+16}" text-anchor="middle" class="cs">“比他们列祖更甚”（士2:19）</text><text x="{cx}" y="{cy+38}" text-anchor="middle" class="cs">基甸之后不再有“太平”</text></svg>'
    s=s.replace('!! 每一圈更坏 !!','每一圈都更坏')
    return f'<figure class="vchart cycle loop rv">{s}<figcaption class="srcline">士2:11–19 是全书的“说明书”：五步循环（3:7–11 俄陀聂一段完整示范）。旋转虚线＝循环不断；它不是圆，而是<b class="k">向下的螺旋</b>。</figcaption></figure>'
JUD=[('俄陀聂','犹大','米所波大米王',8,40,'3:7–11'),('以笏','便雅悯','摩押王伊矶伦',18,80,'3:12–30'),('珊迦','—','非利士',0,0,'3:31'),('底波拉·巴拉','以法莲/拿弗他利','迦南王耶宾',20,40,'4–5'),('基甸','玛拿西','米甸',7,40,'6–8'),('陀拉','以萨迦','—',0,23,'10:1–2'),('睚珥','基列','—',0,22,'10:3–5'),('耶弗他','基列','亚扪',18,6,'10:6–12:7'),('以比赞','伯利恒','—',0,7,'12:8–10'),('以伦','西布伦','—',0,10,'12:11–12'),('押顿','以法莲','—',0,8,'12:13–15'),('参孙','但','非利士',40,20,'13–16')]
def jbars():
    mx=80; o='<div class="jbars rv"><div><span class="hd">士师（支派）</span><span class="hd" style="text-align:right">受压年数 ←</span><span class="hd">→ 太平／作士师年数</span></div>'
    for n,t,e,a,b,r in JUD:
        o+=f'<div><span><b>{n}</b><br><small class="mut">{t} · 士{r}</small></span><span class="o" style="width:{max(a/mx*100,0) if a else 0:.0f}%" title="受 {e} 压制 {a} 年">{a or ""}</span><span class="r" style="width:{b/mx*100 if b else 0:.0f}%" title="{b} 年">{b or ""}</span></div>'
    return o+'</div><p class="srcline">数字据士师记经文（受压：3:8、14；4:3；6:1；10:8；13:1。太平：3:11、30；5:31；8:28；作士师：10:2、3；12:7、9、11、14；15:20）。前四位后有“太平”，<b class="k">基甸以后这个词再没出现</b>；参孙只“开始”拯救（13:5）。</p>'
